const database = data;
const neoDatabase = data;
const databaseByLanguage = data;

function searchNeoFindDatabase(query, language = "pl") {
  const q = String(query ?? "").trim().toLowerCase();
  const list = data[language] || data.pl;
  return list.filter(item =>
    String(item.title || "").toLowerCase().includes(q) ||
    String(item.desc || "").toLowerCase().includes(q)
  );
}

if (typeof window !== "undefined") {
  window.data = data;
  window.database = database;
  window.neoDatabase = neoDatabase;
  window.databaseByLanguage = databaseByLanguage;
  window.searchNeoFindDatabase = searchNeoFindDatabase;
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { data, database, neoDatabase, databaseByLanguage, searchNeoFindDatabase };
}
